"""Development SQLite schema; production uses reviewed forced-RLS migrations."""

TABLES = (
    "gov_controls",
    "gov_grants",
    "gov_findings",
    "gov_risks",
    "gov_exceptions",
    "gov_assessments",
    "gov_receipts",
    "gov_actions",
    "gov_events",
    "gov_monitor",
)
SQLITE = "CREATE TABLE IF NOT EXISTS gov_controls (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,control_key text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,control_key,version));\nCREATE TRIGGER IF NOT EXISTS gov_controls_no_update BEFORE UPDATE ON gov_controls BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_controls_no_delete BEFORE DELETE ON gov_controls BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_grants (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,subject_id text NOT NULL,role text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,subject_id,role,version));\nCREATE TRIGGER IF NOT EXISTS gov_grants_no_update BEFORE UPDATE ON gov_grants BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_grants_no_delete BEFORE DELETE ON gov_grants BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_findings (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,provider text NOT NULL,scope_id text NOT NULL,resource_id text NOT NULL,control_key text NOT NULL,state text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,tenant_id),UNIQUE(tenant_id,provider,scope_id,resource_id,control_key));\nCREATE TABLE IF NOT EXISTS gov_risks (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,state text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,tenant_id));\nCREATE TABLE IF NOT EXISTS gov_exceptions (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,finding_id TEXT NOT NULL,state text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(id,tenant_id),FOREIGN KEY(finding_id,tenant_id) REFERENCES gov_findings(id,tenant_id));\nCREATE TABLE IF NOT EXISTS gov_assessments (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,finding_id TEXT NOT NULL,ordinal INTEGER NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,ordinal));\nCREATE TRIGGER IF NOT EXISTS gov_assessments_no_update BEFORE UPDATE ON gov_assessments BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_assessments_no_delete BEFORE DELETE ON gov_assessments BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_receipts (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,finding_id TEXT NOT NULL,source_id text NOT NULL,receipt_key TEXT NOT NULL,kind text NOT NULL,ordinal INTEGER NOT NULL,fingerprint TEXT NOT NULL,envelope TEXT NOT NULL,signature_hex TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,source_id,receipt_key),UNIQUE(tenant_id,ordinal),FOREIGN KEY(finding_id,tenant_id) REFERENCES gov_findings(id,tenant_id));\nCREATE TRIGGER IF NOT EXISTS gov_receipts_no_update BEFORE UPDATE ON gov_receipts BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_receipts_no_delete BEFORE DELETE ON gov_receipts BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_actions (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,finding_id TEXT NOT NULL,event_key TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,event_key),FOREIGN KEY(finding_id,tenant_id) REFERENCES gov_findings(id,tenant_id));\nCREATE TRIGGER IF NOT EXISTS gov_actions_no_update BEFORE UPDATE ON gov_actions BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_actions_no_delete BEFORE DELETE ON gov_actions BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_events (id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,entity_type text NOT NULL,entity_id text NOT NULL,version INTEGER NOT NULL,payload TEXT NOT NULL,previous_hash TEXT NOT NULL,event_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,entity_type,entity_id,version));\nCREATE TRIGGER IF NOT EXISTS gov_events_no_update BEFORE UPDATE ON gov_events BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TRIGGER IF NOT EXISTS gov_events_no_delete BEFORE DELETE ON gov_events BEGIN SELECT RAISE(ABORT,'Governance history is append-only'); END;\nCREATE TABLE IF NOT EXISTS gov_monitor (tenant_id TEXT PRIMARY KEY,payload TEXT NOT NULL,updated_at TEXT NOT NULL);\nCREATE INDEX IF NOT EXISTS gov_controls_tenant ON gov_controls(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_grants_tenant ON gov_grants(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_findings_tenant ON gov_findings(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_risks_tenant ON gov_risks(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_exceptions_tenant ON gov_exceptions(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_assessments_tenant ON gov_assessments(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_receipts_tenant ON gov_receipts(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_actions_tenant ON gov_actions(tenant_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gov_events_tenant ON gov_events(tenant_id,created_at DESC);"

SQLITE += "\nCREATE INDEX IF NOT EXISTS gov_receipts_target ON gov_receipts(tenant_id,finding_id,kind,ordinal DESC);\nCREATE INDEX IF NOT EXISTS gov_assessments_finding ON gov_assessments(tenant_id,finding_id,ordinal);\nCREATE INDEX IF NOT EXISTS gov_exceptions_finding ON gov_exceptions(tenant_id,finding_id,created_at);"
